UPDATE comment
SET content = #{content}
WHERE comment_id = #{commentId}
    AND member_id = #{memberId}
    AND post_id = #{postId}
    AND deleted_at IS NULL

UPDATE comment
SET deleted_at = NOW()
WHERE comment_id = #{commentId}
    AND member_id = #{memberId}
    AND post_id = #{postId}
    AND deleted_at IS NULL
